const ExcelJS = require('exceljs');

async function searchFile(filename) {
  console.log('Checking ' + filename);
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.readFile(filename);
  wb.eachSheet((sheet, id) => {
    sheet.eachRow((row, rowNumber) => {
      const str = JSON.stringify(row.values);
      if (str.includes('괴정') || str.includes('206-3991') || str.includes('성현') || str.includes('티앤북스')) {
        console.log('Found in ' + filename + ' [' + sheet.name + '] row ' + rowNumber + ': ' + str);
      }
    });
  });
}

